INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES

-- SUBTOPIC 1: Antacids & PPIs (10 flashcards)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','easy','flashcard','What is the mechanism of action of proton pump inhibitors (PPIs)?','["PPIs irreversibly inhibit the H+/K+ ATPase proton pump on the luminal surface of gastric parietal cells, blocking the final step of acid secretion. They are prodrugs activated in the acidic secretory canaliculi and must be taken 30 minutes before meals to be maximally effective."]','A','PPIs are the most potent acid suppressants available. Examples include omeprazole, lansoprazole, pantoprazole, and esomeprazole. Irreversible inhibition means acid secretion is suppressed for 18–24 hours and recovery requires synthesis of new pump protein.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','medium','flashcard','Why does cimetidine cause more drug interactions than other H2 blockers?','["Cimetidine is a potent inhibitor of multiple CYP450 isoenzymes (CYP1A2, CYP2C9, CYP2D6, CYP3A4), significantly reducing the hepatic metabolism of drugs such as warfarin, phenytoin, theophylline, and benzodiazepines, leading to increased plasma levels and toxicity of these drugs."]','A','Ranitidine, famotidine, and nizatidine have minimal CYP450 inhibition and are preferred when drug interactions are a concern. Cimetidine also has antiandrogenic effects (gynaecomastia) due to androgen receptor blockade.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','medium','flashcard','List four adverse effects associated with long-term PPI use.','["1. Hypomagnesaemia (impaired active magnesium transport in the gut). 2. Vitamin B12 deficiency (reduced acid-dependent absorption). 3. Increased hip fracture risk (reduced calcium absorption). 4. Clostridioides difficile infection (reduced gastric acid barrier). Also: increased risk of community-acquired pneumonia."]','A','These effects are dose- and duration-dependent. The FDA issued safety communications on all four risks. PPIs also reduce absorption of ketoconazole, atazanavir, iron, and calcium carbonate (which requires acid for dissolution).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','easy','flashcard','What is the mechanism of action of antacids such as aluminium hydroxide and magnesium trisilicate?','["Antacids directly neutralise gastric acid through chemical buffering reactions. Aluminium hydroxide reacts with HCl to form aluminium chloride and water. They act quickly but have a short duration of action (30–60 minutes when taken on an empty stomach, up to 3 hours after food)."]','A','Aluminium-containing antacids cause constipation; magnesium-containing antacids cause diarrhoea. Many preparations combine both to balance bowel effects. They are fast-acting for symptomatic relief but do not reduce acid secretion.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','hard','flashcard','Which antiretroviral drug has its absorption dramatically reduced by PPIs, and why?','["Atazanavir (a protease inhibitor) requires an acidic gastric environment for solubilisation and absorption. PPIs raise intragastric pH, reducing atazanavir absorption by up to 75%, leading to sub-therapeutic plasma levels and risk of virological failure. Co-administration is generally contraindicated."]','A','The same principle applies to ketoconazole and itraconazole (require acid for dissolution), and calcium carbonate (requires acid for ionisation). Iron absorption is also reduced, though ferrous sulphate (already ionised) is less affected than ferric iron.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','medium','flashcard','What is the mechanism of action of sucralfate and what conditions is it used for?','["Sucralfate is an aluminium salt of sucrose octasulphate. In acidic conditions (pH <4), it polymerises to form a viscous, adhesive gel that binds to ulcer craters, providing a physical barrier against acid, pepsin, and bile. It also stimulates mucus, bicarbonate, and prostaglandin production. Used for peptic ulcer disease and GORD."]','A','Sucralfate requires an acidic environment to work and should not be co-administered with antacids or PPIs (which raise pH). It should be taken 30–60 minutes before meals on an empty stomach. It can bind and reduce absorption of other drugs (quinolones, digoxin, phenytoin) — take other medications 2 hours apart.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','easy','flashcard','What is misoprostol and what is its therapeutic use in gastroenterology?','["Misoprostol is a synthetic PGE1 (prostaglandin E1) analogue. It protects the gastric mucosa by increasing mucus and bicarbonate secretion, enhancing mucosal blood flow, and inhibiting parietal cell acid secretion. It is used to prevent NSAID-induced peptic ulcers. Its main GI side effect is diarrhoea."]','A','Misoprostol is also used in obstetrics (cervical ripening, medical abortion, postpartum haemorrhage) due to its uterotonic effects. It is therefore contraindicated in pregnancy when used for GI indications. A misoprostol-diclofenac combination (Arthrotec) exists for arthritis patients at GI risk.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','medium','flashcard','By approximately what percentage do H2 receptor blockers reduce gastric acid secretion, and what is their primary site of action?','["H2 receptor antagonists reduce gastric acid secretion by approximately 70%. They block histamine H2 receptors on gastric parietal cells, reducing cAMP-mediated activation of the proton pump. They are particularly effective at suppressing fasting (basal) and nocturnal acid secretion."]','A','H2 blockers (cimetidine, ranitidine, famotidine, nizatidine) are less effective than PPIs overall because they only block one of three pathways stimulating the proton pump (histamine, gastrin, acetylcholine). Tolerance (tachyphylaxis) also develops with continuous use. PPIs block the final common pathway regardless of stimulus.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','hard','flashcard','Why should magnesium-containing antacids be avoided in patients with chronic renal failure?','["In chronic renal failure, the kidneys cannot adequately excrete absorbed magnesium, leading to hypermagnesaemia. This can cause progressive toxicity: loss of deep tendon reflexes (Mg2+ >4 mmol/L), hypotension and bradycardia (>5 mmol/L), respiratory depression (>7 mmol/L), and cardiac arrest. Aluminium toxicity (encephalopathy, bone disease) is also a risk with aluminium-containing antacids in renal failure."]','A','Safe antacid options in renal failure include calcium carbonate (which also acts as a phosphate binder) in moderate doses. All antacids should be used cautiously in CKD. Aluminium antacids were previously used as phosphate binders in dialysis patients but aluminium toxicity led to their replacement by calcium and sevelamer-based binders.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','medium','flashcard','Why must PPIs be taken 30 minutes before the first meal of the day?','["PPIs are prodrugs activated only in the acidic secretory canaliculi of active parietal cells. Proton pumps are most active during meal-stimulated acid secretion. Taking the PPI 30 minutes pre-meal ensures peak plasma concentration coincides with maximum pump activation by food, allowing the highest proportion of H+/K+ ATPase to be irreversibly inhibited."]','A','Taking PPIs on an empty stomach at other times of day, or after meals, significantly reduces efficacy. Studies show pre-breakfast timing achieves the greatest acid suppression. PPIs do not inhibit quiescent pumps — only those actively secreting acid. New pump protein synthesis (12–18 hours) gradually restores secretory capacity.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 2: H. pylori Eradication (10 flashcards)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','easy','flashcard','What is the Ghana STG 2017 first-line regimen for H. pylori eradication?','["Omeprazole 20mg twice daily + Amoxicillin 1g twice daily + Clarithromycin 500mg twice daily for 7–14 days. This is standard triple therapy. The PPI raises intragastric pH, enhancing antibiotic stability and H. pylori susceptibility to antibiotics."]','A','This regimen achieves >85% eradication where clarithromycin resistance is low. In penicillin-allergic patients: replace amoxicillin with metronidazole 400mg BD. Compliance with the full course is critical. Test of cure (urea breath test or stool antigen) should be performed 4 weeks after completing therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','medium','flashcard','What is bismuth quadruple therapy for H. pylori and when is it used?','["Bismuth quadruple therapy: PPI (standard dose BD) + bismuth subcitrate 120mg QDS + metronidazole 400mg TDS + tetracycline 500mg QDS for 14 days. Used when clarithromycin resistance is suspected, as a second-line regimen after triple therapy failure, or as primary therapy in high-resistance regions."]','A','Bismuth quadruple therapy achieves >90% eradication regardless of clarithromycin resistance status. Bismuth directly kills H. pylori by disrupting its cell wall, inhibiting urease, and preventing mucosal adhesion. Side effects of bismuth include black stools and dark tongue (harmless). Tetracycline chelation with dairy and antacids must be considered.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','medium','flashcard','How and when should the urea breath test be performed to confirm H. pylori eradication?','["The urea breath test (UBT) should be performed at least 4 weeks after completing antibiotic therapy and at least 2 weeks after stopping PPIs. The patient ingests 13C or 14C-labelled urea; if H. pylori is present, its urease cleaves the urea, producing labelled CO2 detected in exhaled breath. Antibiotics and PPIs must be stopped before testing to avoid false-negative results."]','A','The stool antigen test (HpSA) is an equivalent non-invasive test of cure. Serology (IgG antibodies) is NOT used for test of cure because antibody titres remain elevated for months after successful eradication, making it impossible to distinguish current from past infection.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','easy','flashcard','What antibiotic replaces amoxicillin in H. pylori triple therapy for penicillin-allergic patients?','["Metronidazole 400mg twice daily replaces amoxicillin in patients with penicillin allergy. The resulting regimen is: Omeprazole 20mg BD + Metronidazole 400mg BD + Clarithromycin 500mg BD for 7–14 days. This is the recommended alternative first-line regimen in Ghana STG 2017."]','A','Metronidazole is a nitroimidazole antibiotic that forms toxic free radicals in anaerobic/microaerophilic organisms like H. pylori, damaging bacterial DNA. Resistance to metronidazole is higher than to amoxicillin in many regions, which may reduce efficacy. Alcohol should be avoided during and for 48 hours after metronidazole (disulfiram-like reaction).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','hard','flashcard','How does H. pylori eradication affect peptic ulcer recurrence rates?','["Without eradication, duodenal ulcer recurrence is approximately 80% per year. Successful H. pylori eradication reduces recurrence to <5% per year — effectively curing the underlying cause of ulcer disease in H. pylori-positive patients. H. pylori is present in ~95% of duodenal ulcers and ~70% of gastric ulcers."]','A','H. pylori eradication is the most cost-effective intervention in gastroenterology. It also reduces gastric cancer risk (H. pylori is a Group 1 carcinogen for gastric adenocarcinoma and is associated with MALT lymphoma). MALT lymphoma may regress completely with eradication alone in early stages.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','medium','flashcard','Why is increasing clarithromycin resistance a problem for H. pylori eradication?','["Clarithromycin resistance rates above 15–20% significantly reduce the efficacy of standard triple therapy below the acceptable 80% eradication threshold. Resistance occurs via point mutations in H. pylori 23S rRNA that prevent clarithromycin binding to the 50S ribosomal subunit. Regions with high resistance rates should use bismuth quadruple therapy or culture-guided therapy as first-line."]','A','Increasing antibiotic resistance globally is a major challenge in H. pylori management. Metronidazole resistance is even more common (30–40%) but is partially overcome by higher doses. Amoxicillin resistance remains low (<1%). Pre-treatment susceptibility testing or use of local resistance data should guide regimen choice.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','easy','flashcard','What additional role does bismuth subcitrate have beyond H. pylori eradication?','["Bismuth subcitrate also has mild antacid properties and is used for traveller''s diarrhoea (bismuth subsalicylate/Pepto-Bismol). It directly kills H. pylori by disrupting its cell wall, inhibiting urease (preventing ammonia production), and preventing bacterial adhesion to gastric epithelium. It colours stools and tongue black (harmless)."]','A','Bismuth compounds have been used for GI complaints for centuries. In addition to H. pylori activity, bismuth has mild astringent and antisecretory properties useful in non-specific diarrhoea. It does not inhibit the proton pump or H2 receptors. The black discolouration is due to bismuth sulphide formation in the gut.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','hard','flashcard','Why does including a PPI in H. pylori eradication regimens significantly improve antibiotic efficacy?','["PPIs raise intragastric pH above 6, which: (1) improves the stability of amoxicillin and clarithromycin at higher pH; (2) increases H. pylori susceptibility to antibiotics as bacteria are most vulnerable to antibiotics during active replication, which occurs preferentially at higher pH; (3) reduces H. pylori bacterial load by impairing its urease-dependent survival mechanism."]','A','The dose and potency of the PPI in triple therapy directly correlates with eradication success. More potent acid suppression (e.g., esomeprazole 40mg BD vs omeprazole 20mg BD) improves eradication rates by approximately 5–10%. This is why rabeprazole and esomeprazole may be slightly preferred in some meta-analyses.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','medium','flashcard','What is the recommended duration of first-line triple therapy for H. pylori in the Ghana STG 2017?','["7–14 days. Seven-day regimens are adequate where clarithromycin resistance rates are low (<15%). Fourteen-day courses improve eradication rates by approximately 5% and are preferred in areas with higher resistance rates or as the default where resistance data are unavailable."]','A','Patient compliance with the full antibiotic course is critical — partial treatment is a major cause of eradication failure and selects for resistant strains. Patients should be counselled that all medications must be completed even if symptoms resolve before the course ends. Side effects (metallic taste, nausea, diarrhoea) are common but usually mild and transient.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','hard','flashcard','Why must PPIs be stopped at least 2 weeks before a urea breath test?','["PPIs suppress H. pylori urease activity and reduce bacterial load without eliminating the organism. Since the urea breath test relies on H. pylori urease cleaving 13C-labelled urea to produce 13CO2, PPI-mediated urease suppression reduces CO2 production below the detection threshold, producing false-negative results. Antibiotics should be stopped 4 weeks before testing."]','A','This is a critical pre-analytical requirement often missed in clinical practice. A false-negative UBT leads to premature declaration of eradication success when H. pylori persists, allowing ongoing mucosal damage and ulcer recurrence. The stool antigen test has the same PPIs requirement: stop 2 weeks before testing.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 3: Antiemetics (10 flashcards)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','easy','flashcard','What is the mechanism of action of ondansetron and what is it primarily used for?','["Ondansetron is a selective 5-HT3 receptor antagonist. It blocks serotonin receptors in the chemoreceptor trigger zone (CTZ), nucleus tractus solitarius, and peripheral vagal afferents in the GI tract. It is primarily used for chemotherapy-induced and post-operative nausea and vomiting. It does not cause extrapyramidal side effects."]','A','5-HT3 receptors are activated by serotonin released from enterochromaffin cells during chemotherapy-induced gut mucosal damage. Ondansetron blocks this signal at both peripheral and central 5-HT3 receptors. It is less effective for motion sickness (predominantly vestibular/cholinergic pathway). QT prolongation is a rare but important cardiac side effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','medium','flashcard','What extrapyramidal side effects can metoclopramide cause and why?','["Metoclopramide crosses the BBB and blocks D2 receptors in the basal ganglia (nigrostriatal pathway). This causes: acute dystonia (involuntary muscle spasms, torticollis, oculogyric crisis), akathisia (motor restlessness), drug-induced parkinsonism (tremor, rigidity, bradykinesia), and with prolonged use, tardive dyskinesia (irreversible repetitive movements)."]','A','Extrapyramidal effects are more common in young women, children, and the elderly. Acute dystonia is treated with procyclidine (anticholinergic) or benzodiazepines. Metoclopramide should not be used for more than 5 days without reassessment, per MHRA guidance. It is absolutely contraindicated in Parkinson''s disease.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','medium','flashcard','How does domperidone differ from metoclopramide in its pharmacological profile?','["Both are D2 receptor antagonists. Key difference: domperidone does NOT cross the blood-brain barrier (large molecular weight, high polarity, P-gp substrate), so it acts only peripherally (gut D2 receptors) and at the area postrema CTZ (which is outside the BBB). This means far fewer extrapyramidal effects but no central antiemetic effect from BBB penetration. Domperidone prolongs QT interval (cardiac risk)."]','A','Domperidone is the antiemetic/prokinetic of choice in Parkinson''s disease patients (does not worsen motor symptoms). However, it should be used at the lowest effective dose for the shortest time due to QT prolongation risk. It is associated with sudden cardiac death, particularly at doses >30mg/day or in patients >60 years.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','easy','flashcard','Which antiemetic is most effective for motion sickness and what is its mechanism?','["Hyoscine (scopolamine) — a muscarinic (M1) receptor antagonist. It blocks cholinergic transmission in the vestibular nucleus and vomiting centre, preventing motion-induced nausea and vomiting. Available as a transdermal patch (applied behind the ear 4 hours before travel), oral tablets, or injection. Side effects: dry mouth, blurred vision, sedation."]','A','Hyoscine is more effective than antihistamines for motion sickness. Cyclizine (H1 antihistamine) is second-line. Ondansetron is NOT effective for motion sickness as the pathway is primarily cholinergic/vestibular rather than serotoninergic. Hyoscine must be used with caution in elderly patients due to central anticholinergic effects (confusion, urinary retention).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','hard','flashcard','Why is the chemoreceptor trigger zone (CTZ) uniquely sensitive to blood-borne emetic stimuli?','["The CTZ is located in the area postrema on the floor of the fourth ventricle, which lacks a normal blood-brain barrier. This allows the CTZ to directly sample circulating blood and CSF for emetic stimuli (drugs, toxins, uraemia, hypoxia, pregnancy hormones). D2 and 5-HT3 receptors in the CTZ are the main drug targets. Drugs that do not cross the BBB (domperidone) can still act on the CTZ."]','A','The area postrema''s lack of BBB is exploited therapeutically: apomorphine (a D2 agonist that does not cross the BBB) can trigger vomiting by acting on the CTZ, making it useful for inducing emesis in poisoning (though this use is now largely abandoned). Conversely, D2 antagonists acting at the CTZ suppress drug/toxin-induced nausea.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','medium','flashcard','What is the mechanism of action of cyclizine and what type of nausea is it most effective for?','["Cyclizine is an H1 antihistamine with additional anticholinergic properties. It acts on histamine H1 receptors in the vomiting centre (nucleus tractus solitarius) and vestibular pathways. It is most effective for: motion sickness, labyrinthitis (vestibular disorders), and opioid-induced nausea (opioids stimulate vestibular pathways). Side effects include sedation and dry mouth."]','A','Cyclizine is useful as an adjunct to opioid analgesics to prevent nausea (often prescribed as co-cyclizine with opioids). It is often the antiemetic of first choice for nausea with a vestibular component. It is less effective for CINV (chemotherapy-induced) where 5-HT3 antagonists are superior.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','hard','flashcard','What is the triple antiemetic regimen for highly emetogenic chemotherapy (HEC) and what is the rationale for each component?','["1. 5-HT3 antagonist (ondansetron/granisetron) — blocks peripheral and central serotonin signalling triggered by gut mucosal damage. 2. Dexamethasone — reduces prostaglandin synthesis, modulates 5-HT3 receptors; effective for acute and delayed CINV. 3. NK1 receptor antagonist (aprepitant/fosaprepitant) — blocks substance P at NK1 receptors in the vomiting centre; essential for preventing delayed CINV (24–120 hours post-chemotherapy)."]','A','The combination targets three distinct emetic pathways, achieving superior control (>90% complete response) compared to any single or dual agent. Aprepitant is given orally on days 1–3. For highly emetogenic regimens like cisplatin, olanzapine (D2/5-HT antagonist) is added as a fourth agent in some guidelines for refractory CINV.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','easy','flashcard','What long-term adverse effect is associated with chronic prochlorperazine use?','["Tardive dyskinesia — irreversible repetitive involuntary movements (lip-smacking, tongue protrusion, grimacing, choreoathetoid limb movements) caused by upregulation and supersensitivity of dopamine D2 receptors following chronic blockade. It occurs after months to years of continuous use of D2 antagonist antipsychotics/antiemetics."]','A','Prochlorperazine (a phenothiazine) is a potent D2 antagonist used as an antiemetic. Unlike metoclopramide (limited to 5-day courses), prochlorperazine is sometimes prescribed long-term for nausea, which risks tardive dyskinesia. Acute extrapyramidal effects (dystonia, akathisia) are also common. It should not be used long-term as an antiemetic. Ondansetron is safer for chronic use.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','medium','flashcard','What is the dual mechanism by which metoclopramide acts as both an antiemetic and a prokinetic?','["Antiemetic: D2 receptor antagonism in the CTZ (area postrema), blocking dopamine-mediated nausea signals. Prokinetic: (1) D2 antagonism in the enteric nervous system, removing dopamine''s inhibitory effect on acetylcholine release; (2) 5-HT4 agonism, directly stimulating cholinergic release from enteric neurons — together increasing LOS tone, accelerating gastric emptying, and enhancing duodenal motility."]','A','This dual mechanism makes metoclopramide useful for conditions where both nausea and impaired motility coexist (gastroparesis, GORD, post-operative ileus). However, the central D2 antagonism that causes its antiemetic effect also causes extrapyramidal side effects, limiting its use. Domperidone achieves the peripheral prokinetic effect without central side effects.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','medium','flashcard','What is the proposed antiemetic mechanism of dexamethasone?','["Dexamethasone''s antiemetic mechanism is not fully understood but is thought to involve: (1) inhibition of prostaglandin synthesis via phospholipase A2 inhibition; (2) downregulation of 5-HT3 receptor expression in the gut; (3) reduction of blood-brain barrier permeability to emetic stimuli; (4) possible direct suppression of nucleus tractus solitarius neuronal activity. It is synergistic with 5-HT3 antagonists for both acute and delayed CINV."]','A','Dexamethasone is given as a single pre-chemotherapy dose (8mg IV) for acute CINV and continued orally (4mg BD) for 3 days for delayed CINV. Side effects with short courses are generally mild (insomnia, hyperglycaemia, mood elevation). It is used in combination with other antiemetics rather than as monotherapy.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 4: Laxatives & Antidiarrhoeals (10 flashcards)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','easy','flashcard','What is the mechanism of action of loperamide?','["Loperamide is a synthetic mu-opioid receptor agonist that acts on the myenteric plexus of the gut wall. It reduces propulsive peristalsis, increases ileocaecal and anal sphincter tone, and decreases intestinal fluid and electrolyte secretion, resulting in slower transit and firmer stools. It does not cross the BBB (P-glycoprotein efflux), so there are no CNS opioid effects."]','A','Loperamide is the drug of choice for non-specific acute diarrhoea and traveller''s diarrhoea (without dysentery). Adult dose: 4mg initially, then 2mg after each loose stool (max 16mg/day). CONTRAINDICATED in bloody diarrhoea, dysentery, C. difficile infection, and in children under 12. Slowing motility in invasive bacterial diarrhoea can worsen infection and cause toxic megacolon.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','medium','flashcard','What are the components of the WHO/Ghana STG oral rehydration solution (ORS) per litre of water and what is the rationale for each?','["Per litre of clean water: Sodium chloride 3.5g (replace sodium lost in diarrhoea and drive glucose-sodium co-transport), Sodium citrate 2.9g (correct metabolic acidosis from diarrhoea), Potassium chloride 1.5g (replace potassium losses), Glucose 20g (drives Na+ absorption via SGLT1 co-transporter, pulling water with it). Total osmolarity ~245 mOsm/L."]','A','The key physiological principle is that glucose-sodium co-transport (SGLT1) remains intact even in secretory diarrhoea. Glucose facilitates sodium absorption, which osmotically pulls water from the gut lumen into the body. This is why ORS works even in cholera. WHO now recommends low-osmolarity ORS (245 mOsm/L vs original 311 mOsm/L) which reduces vomiting and diarrhoea volume in children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','medium','flashcard','What are the different classes of laxatives with an example of each?','["1. Bulk-forming: ispaghula/psyllium, methylcellulose (increase stool bulk, require adequate fluid). 2. Osmotic: lactulose, macrogol/PEG, magnesium salts (draw water into bowel lumen). 3. Stimulant: senna, bisacodyl (stimulate myenteric nerves and colonic secretion). 4. Faecal softeners: docusate sodium (surfactant, softens stool). 5. Lubricants: liquid paraffin (lubricates stool passage)."]','A','Each class has different indications, onsets, and side effects. Bulk-forming agents are safest for long-term use but require adequate fluid. Stimulants are fastest acting. Osmotic agents are effective for impaction (macrogol) and hepatic encephalopathy (lactulose). Docusate is mildest. Stimulant laxatives with chronic use can cause melanosis coli and electrolyte disturbances.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','easy','flashcard','Why do bulk-forming laxatives require adequate fluid intake to be effective?','["Bulk-forming agents (ispaghula/psyllium, methylcellulose) are hydrophilic polysaccharides that absorb water and expand to form a viscous gel, increasing stool bulk and stimulating peristalsis. Without adequate fluid intake (minimum 6–8 glasses daily), the fibre absorbs available intestinal water, potentially worsening constipation or causing intestinal obstruction — the opposite of the intended effect."]','A','Bulk-forming agents are the safest laxative for long-term use and are preferred in pregnancy. They are not suitable for patients with difficulty swallowing (risk of oesophageal obstruction) or those who cannot maintain adequate fluid intake. They take 2–3 days to work. They are also used to manage diarrhoea (normalise stool consistency in IBS).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','hard','flashcard','Why does lactulose cause bloating and flatulence, and why is this mechanism also therapeutically useful in hepatic encephalopathy?','["Lactulose reaches the colon undigested and is fermented by colonic bacteria, producing short-chain fatty acids (acidifying the colon to pH <6) and gases (H2, CO2, CH4) — causing bloating and flatulence. The colonic acidification is therapeutically useful in hepatic encephalopathy: NH3 (absorbed, crosses BBB) is protonated to NH4+ (cannot be absorbed, excreted in faeces), reducing systemic ammonia levels."]','A','This same mechanism makes lactulose less tolerable than macrogol for simple constipation. Macrogol works by retaining water through hydrogen bonding without bacterial fermentation, so it causes no bloating. For hepatic encephalopathy, lactulose is titrated to 2–3 soft stools/day to optimise colonic acidification. Excessive use causes diarrhoea, dehydration, and electrolyte disturbances.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','medium','flashcard','What is the mechanism of action of senna as a stimulant laxative?','["Senna contains anthraquinone glycosides (sennosides A and B) that are inactive as ingested. Colonic bacteria hydrolyse them to active anthraquinone metabolites (rhein anthrone). These directly stimulate the myenteric nerve plexus, increasing propulsive peristaltic contractions. They also promote electrolyte and water secretion into the colonic lumen. Onset: 8–12 hours."]','A','Stimulant laxatives (senna, bisacodyl) are effective for acute constipation and bowel preparation. Long-term use can cause: hypokalaemia and electrolyte disturbances, cathartic colon (atony from chronic stimulation), melanosis coli (dark pigmentation from anthraquinone deposition — harmless), and dependence. They are safe for short-term use in pregnancy and postoperatively.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','easy','flashcard','What two GI side effects are expected with oral iron supplementation and why?','["1. Constipation — iron reduces gut motility (may involve hydrogen sulphide depletion). 2. Black/dark stools — unabsorbed ferrous iron combines with hydrogen sulphide from gut bacteria to form black iron sulphide. Patients must be counselled that black stools are expected and do not indicate GI bleeding (unlike melaena, which has a tarry consistency and offensive odour)."]','A','Other GI side effects of oral iron include nausea, epigastric pain, and diarrhoea (less common). Ferrous sulphate 200mg TDS is standard. Taking iron after food reduces GI side effects but also reduces absorption. Vitamin C (ascorbic acid) enhances ferric iron reduction to ferrous iron, improving absorption. Avoid co-administration with antacids, tetracyclines, and fluoroquinolones (chelation).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','medium','flashcard','How does macrogol (polyethylene glycol) work as a laxative and how does it differ from lactulose?','["Macrogol is a high-molecular-weight inert polymer that retains water molecules through hydrogen bonding in the gut lumen, softening stool and increasing volume. Unlike lactulose, macrogol is NOT fermented by gut bacteria, so it does not cause bloating or flatulence. It is not absorbed and is not metabolised. It is effective for constipation and faecal impaction."]','A','Macrogol is the preferred osmotic laxative in most current guidelines due to its superior tolerability compared to lactulose (no bloating, no gas). High-dose macrogol (e.g., Movicol 8 sachets dissolved in 1L water over 6 hours) is used for faecal disimpaction. It is safe in pregnancy and can be used in renal failure (unlike magnesium-containing osmotic agents).','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','hard','flashcard','Why is loperamide contraindicated in bloody diarrhoea (dysentery)?','["In dysentery (invasive bacterial diarrhoea from Shigella, EHEC O157, Salmonella, Campylobacter), slowing gut motility with loperamide prolongs contact time between invasive organisms/toxins and the intestinal mucosa. This worsens mucosal invasion, increases toxin absorption (including Shiga toxin from EHEC, which causes haemolytic uraemic syndrome), and risks toxic megacolon. These bacteria must be rapidly expelled."]','A','The distinction between secretory diarrhoea (ORS + loperamide appropriate) and invasive/bloody diarrhoea (antibiotics + ORS; loperamide contraindicated) is a critical clinical decision. Clinical clues for invasive diarrhoea: blood/mucus in stool, fever, severe abdominal pain, systemic toxicity. If in doubt, stool microscopy and culture should guide management.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','medium','flashcard','What is docusate sodium and what is its mechanism of action?','["Docusate sodium is a faecal softener (emollient/surfactant laxative). It acts as a detergent, reducing surface tension and allowing water and fats to penetrate and soften hardened stool. It is the mildest laxative type, taking 1–3 days to work. Primarily used when straining must be avoided (post-MI, post-surgical, haemorrhoids, anal fissure)."]','A','Docusate has no effect on colonic motility or secretion — it only softens stool. It is not effective for moderate-to-severe constipation. It can be used in pregnancy. Some evidence suggests it can increase the absorption of mineral oil if taken together (avoid concurrent use). It is often combined with stimulant laxatives (co-danthrusate = docusate + dantron) for palliative care.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 5: IBD Pharmacotherapy (10 flashcards)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','easy','flashcard','What is the first-line pharmacological treatment for mild-to-moderate ulcerative colitis?','["5-Aminosalicylates (5-ASA): mesalazine (mesalamine) or sulfasalazine. They act topically on the colonic mucosa, reducing inflammation through inhibition of prostaglandin synthesis, NF-kB signalling, and reactive oxygen species production. Mesalazine is available as oral and rectal formulations (suppositories, enemas). Rectal preparations are preferred for proctitis/distal UC."]','A','Sulfasalazine is a prodrug split by colonic bacteria to mesalazine (active) + sulfapyridine (responsible for most side effects: nausea, headache, haemolytic anaemia, oligospermia, folate deficiency). Mesalazine alone avoids sulfapyridine-related side effects. 5-ASA drugs are used for both induction and maintenance of remission in UC but are less effective in Crohn''s disease.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','medium','flashcard','What is azathioprine, how does it work in IBD, and why must TPMT be checked before starting?','["Azathioprine is an immunosuppressive prodrug metabolised to 6-mercaptopurine (6-MP), which is further converted to 6-thioguanine nucleotides (6-TGN) — the active cytotoxic metabolites that inhibit purine synthesis and T-cell proliferation. TPMT (thiopurine methyltransferase) inactivates 6-MP. Low TPMT activity → 6-MP accumulates as cytotoxic 6-TGN → severe bone marrow suppression (potentially fatal leucopenia)."]','A','Approximately 10% of people are heterozygous for low TPMT activity and 0.3% are homozygous (essentially absent TPMT). Homozygous patients should not receive azathioprine. Heterozygous patients require dose reduction and close monitoring. Regular FBC monitoring is essential for all patients on azathioprine. Allopurinol interaction: blocks xanthine oxidase → markedly increases 6-TGN → severe toxicity (reduce azathioprine dose by 75% if combined).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','medium','flashcard','What is the mechanism of infliximab and adalimumab in IBD treatment?','["Infliximab (chimeric mouse-human) and adalimumab (fully human) are monoclonal antibodies that bind to and neutralise TNF-α (tumour necrosis factor-alpha), a key pro-inflammatory cytokine driving intestinal inflammation in IBD. They bind both soluble TNF-α and membrane-bound TNF-α, inducing apoptosis of TNF-expressing immune cells (important for fistula closure in Crohn''s). Used for moderate-to-severe IBD refractory to immunomodulators."]','A','Pre-treatment screening is mandatory: TB (IGRA/Mantoux + CXR), hepatitis B serology, and ensure vaccinations are up to date (live vaccines contraindicated once started). Risk of reactivating latent TB, hepatitis B, and opportunistic infections (Pneumocystis, invasive fungal infections). Infliximab is IV; adalimumab is subcutaneous (self-injected), preferred for maintenance.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','hard','flashcard','What are the IBD-specific indications for vedolizumab and what makes it gut-selective?','["Vedolizumab is indicated for moderate-to-severe UC and Crohn''s disease, particularly after failure of anti-TNF therapy. It is gut-selective because it blocks α4β7 integrin on gut-homing lymphocytes, preventing their binding to MAdCAM-1 (mucosal addressin cell adhesion molecule-1) on gut vascular endothelium. MAdCAM-1 is expressed specifically in gut-associated vasculature, not in the brain or other organs."]','A','This gut-selectivity means vedolizumab has a favourable safety profile compared to systemic immunosuppressants — no increased risk of systemic infections or PML (unlike natalizumab which blocks α4 integrin globally and can cause PML by allowing JC virus into the CNS). Vedolizumab has a slow onset (12–14 weeks), so it is not suitable for acute severe IBD flares.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','easy','flashcard','What adverse effects are associated with sulfasalazine that are not seen with mesalazine alone?','["Sulfapyridine component causes: nausea and vomiting, headache, haemolytic anaemia (in G6PD-deficient patients), folate deficiency (requires folic acid supplementation), reversible oligospermia and abnormal sperm morphology (male infertility, reversible on stopping), and rare hypersensitivity reactions (rash, Stevens-Johnson syndrome, interstitial nephritis). Mesalazine alone avoids all sulfapyridine-mediated side effects."]','A','When male patients on sulfasalazine wish to conceive, switching to mesalazine resolves the oligospermia within 2–3 months. All patients on sulfasalazine should take folic acid 5mg daily. Both sulfasalazine and mesalazine can rarely cause nephrotoxicity (interstitial nephritis) — renal function should be monitored annually.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','medium','flashcard','Why is budesonide preferred over systemic prednisolone for mild-to-moderate Crohn''s ileitis?','["Budesonide undergoes >90% first-pass hepatic metabolism, giving only ~10% systemic bioavailability despite high local anti-inflammatory potency. It is formulated as pH-dependent capsules delivering drug to the terminal ileum and ascending colon. This achieves local anti-inflammatory effect with dramatically fewer systemic corticosteroid side effects (adrenal suppression, osteoporosis, hyperglycaemia, Cushingoid appearance, infection risk)."]','A','Budesonide is NOT equivalent to systemic steroids for severe IBD — it is insufficient for moderate-to-severe disease or systemic complications. It should not be used as a maintenance drug (still causes adrenal suppression with long-term use, just less than prednisolone). Prednisolone is still required for severe flares. Budesonide is also used in PBC (Budenofalk) and microscopic colitis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','hard','flashcard','What is the dangerous interaction between azathioprine and allopurinol in IBD patients?','["Allopurinol inhibits xanthine oxidase (XO), one of three competing enzymes metabolising 6-mercaptopurine (6-MP, azathioprine''s active metabolite). Blocking XO shunts 6-MP away from inactive metabolites and towards 6-thioguanine nucleotides (6-TGN), increasing cytotoxic 6-TGN levels 4–5 fold. This causes severe, potentially fatal bone marrow suppression (profound leucopenia, pancytopenia, sepsis)."]','A','If allopurinol is clinically necessary in a patient on azathioprine (e.g., for gout), the azathioprine dose MUST be reduced by 75% and FBC monitored very closely. Alternatively, use febuxostat (XO inhibitor) — same interaction, same precautions. Some IBD centres deliberately combine low-dose azathioprine (25mg) with allopurinol (100mg) to shift metabolism towards 6-TGN for patients who are 6-TGN hypo-responders (high 6-methylmercaptopurine / low 6-TGN ratio).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','medium','flashcard','What is ustekinumab and for which IBD indications is it approved?','["Ustekinumab is a fully human monoclonal antibody that binds to the p40 subunit shared by IL-12 and IL-23, blocking both cytokines. IL-12 drives Th1 differentiation (IFN-γ production); IL-23 drives Th17 differentiation (IL-17 production). Both are key inflammatory pathways in IBD. Approved for moderate-to-severe Crohn''s disease and ulcerative colitis in patients who have failed anti-TNF therapy or are anti-TNF intolerant."]','A','Ustekinumab has a favourable safety profile (lower infection risk than anti-TNF drugs, no TB reactivation association). It is given as a single IV induction dose followed by SC maintenance injections every 8–12 weeks. Unlike vedolizumab, it works systemically and can also be used for psoriasis and psoriatic arthritis, which often co-exist with IBD.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','easy','flashcard','What is the role of corticosteroids in IBD and why are they not used for maintenance?','["Corticosteroids (prednisolone 40mg/day for UC; prednisolone/budesonide for Crohn''s) induce remission in moderate-to-severe IBD flares by broadly suppressing inflammatory cytokine production and leucocyte migration. They are NOT used for maintenance because: they do not prevent relapse, are not mucosal healing agents, and long-term use causes serious side effects (osteoporosis, adrenal suppression, diabetes, hypertension, cataracts, infections)."]','A','Steroid-dependence (inability to taper without relapse) and steroid-refractoriness (failure to respond despite adequate dose) are key decision points for escalating to immunomodulators (azathioprine) or biologics (anti-TNF). Patients requiring >2 courses of steroids per year should be considered for steroid-sparing therapy. All patients on long-term steroids need calcium, vitamin D, and bisphosphonate prophylaxis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','hard','flashcard','What pre-treatment screening is mandatory before starting anti-TNF therapy (infliximab/adalimumab)?','["1. TB screening: IGRA (QuantiFERON-TB Gold) or Mantoux test + chest X-ray. Latent TB must be treated with isoniazid for 6–9 months before starting. 2. Hepatitis B serology: HBsAg, anti-HBc, anti-HBs — reactivation of chronic/occult HBV can cause fatal hepatitis; antiviral prophylaxis (tenofovir/entecavir) needed if HBsAg+ or anti-HBc+. 3. Live vaccine update (MMR, varicella) — cannot be given once on anti-TNF. 4. HIV testing recommended."]','A','Anti-TNF-mediated immunosuppression reactivates latent infections by reducing TNF-α-dependent granuloma integrity. Cases of disseminated TB, histoplasmosis, coccidioidomycosis, aspergillosis, and Pneumocystis jirovecii pneumonia have been reported. The risk of serious infection is 2-3 fold higher with anti-TNF than with conventional immunosuppressants.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 6: Antispasmodics & Prokinetics (10 flashcards)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','easy','flashcard','What is the mechanism of action of hyoscine butylbromide (Buscopan) and what conditions is it used for?','["Hyoscine butylbromide is a quaternary ammonium anticholinergic compound that blocks muscarinic M3 receptors on GI smooth muscle, producing smooth muscle relaxation and reducing painful spasms. Used for: IBS (intestinal spasm), renal colic, biliary colic, and ureteric spasm. Because it is quaternary (charged), it has minimal CNS penetration and fewer central anticholinergic effects."]','A','Despite being quaternary, peripheral anticholinergic side effects can occur: dry mouth, blurred vision (cycloplegia), urinary hesitancy/retention, tachycardia, and constipation. It is contraindicated in narrow-angle glaucoma, myasthenia gravis, and should be used with caution in BPH. Available as tablets and IV/IM injection (for acute colic).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','medium','flashcard','Why is mebeverine preferred over hyoscine in patients with BPH or glaucoma?','["Mebeverine is a direct-acting smooth muscle relaxant (musculotropic antispasmodic) that acts directly on intestinal smooth muscle calcium channels without any anticholinergic activity. It does not block muscarinic receptors anywhere in the body, so it causes no urinary retention (safe in BPH), no increase in intraocular pressure (safe in glaucoma), no dry mouth, and no blurred vision."]','A','Mebeverine is used in IBS for colonic spasm relief. It is well tolerated for long-term use. Unlike anticholinergic antispasmodics, it can be used in elderly patients without concern about falls risk from urinary retention or confusion. It has no known drug interactions. Its precise molecular mechanism involves inhibiting sodium influx and reducing intracellular calcium availability in smooth muscle.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','medium','flashcard','What receptor does erythromycin agonise to produce its prokinetic effect and at what dose?','["At low, sub-antimicrobial doses (1–3 mg/kg/day oral or IV, typically 250mg TDS orally), erythromycin acts as a motilin receptor agonist. Motilin is an endogenous peptide that triggers the migrating motor complex (MMC) — powerful interdigestive stomach contractions. Erythromycin mimics motilin, stimulating gastric emptying and small intestinal motility."]','A','Erythromycin as a prokinetic is used for gastroparesis (particularly post-vagotomy and diabetic) and to facilitate nasogastric/nasojejunal tube placement. Tachyphylaxis (rapid tolerance) develops within days to weeks with continuous use, limiting long-term utility. Higher (antimicrobial) doses can cause GI cramping, diarrhoea, and QT prolongation (particularly IV). It also inhibits CYP3A4.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','easy','flashcard','Why is domperidone preferred over metoclopramide as a prokinetic in Parkinson''s disease?','["In Parkinson''s disease, central dopamine pathways are already depleted and dopaminergic medication (levodopa/dopamine agonists) is the primary treatment. Metoclopramide crosses the BBB and blocks central D2 receptors, dramatically worsening Parkinsonism (tremor, rigidity, bradykinesia) — it is absolutely contraindicated. Domperidone does not cross the BBB, so it can manage gastroparesis and nausea without affecting central dopamine function."]','A','Domperidone is also used to manage nausea from dopamine agonists (apomorphine, ropinirole) used in Parkinson''s disease. It should be used at the lowest effective dose due to QT prolongation risk. ECG monitoring before and during treatment is recommended. Dose: 10mg before meals TDS, maximum 30mg/day, for the shortest possible duration.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','hard','flashcard','What is prucalopride and what is its advantage over older prokinetics like cisapride?','["Prucalopride is a highly selective, high-affinity 5-HT4 receptor agonist used for chronic constipation. It stimulates propulsive peristalsis in the colon by enhancing acetylcholine and CGRP release from enteric neurons. Unlike cisapride and tegaserod (older 5-HT4 agonists), prucalopride has minimal affinity for cardiac hERG potassium channels and does not prolong the QT interval, making it cardiovascularly safe."]','A','Cisapride was withdrawn in 2000 due to fatal cardiac arrhythmias (QT prolongation → Torsades de pointes) from hERG channel blockade. Prucalopride''s 5-HT4 selectivity avoids this. It is taken orally once daily (2mg; 1mg in elderly). Clinical trials show it significantly increases complete spontaneous bowel movements per week in chronic constipation not responding to laxatives.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','medium','flashcard','What is the cardiac adverse effect of domperidone and how should it be monitored?','["Domperidone prolongs the cardiac QT interval by blocking hERG (IKr) potassium channels in cardiac myocytes, slowing ventricular repolarisation. This can lead to Torsades de pointes (a polymorphic ventricular tachycardia) and sudden cardiac death. Risk is greatest in patients >60 years, with cardiac disease, electrolyte disturbances (hypokalaemia, hypomagnesaemia), or at doses >30mg/day."]','A','Monitoring: baseline ECG before starting, repeat if symptoms develop (palpitations, syncope). Avoid combining domperidone with other QT-prolonging drugs (erythromycin, fluconazole, antipsychotics). The MHRA restricted domperidone in 2014: maximum 10mg TDS, maximum 30mg/day, shortest necessary duration. Contraindicated in patients with pre-existing QT prolongation or significant cardiac disease.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','medium','flashcard','What is metoclopramide''s prokinetic mechanism and what are its therapeutic uses beyond antiemesis?','["Prokinetic mechanism: D2 receptor antagonism removes dopamine-mediated inhibition of acetylcholine release in the enteric nervous system, plus 5-HT4 agonism directly stimulates cholinergic propulsive activity. Net effect: increases lower oesophageal sphincter (LOS) tone, accelerates gastric emptying, enhances duodenal motility. Therapeutic uses: gastroparesis (diabetic, post-surgical), GORD (LOS incompetence), and as a prokinetic before endoscopy or nasogastric intubation."]','A','Metoclopramide should not be used for >5 days without reassessment (MHRA guidance). It is contraindicated in Parkinson''s disease, phaeochromocytoma (may precipitate hypertensive crisis by releasing catecholamines), and after GI surgery where stimulation of peristalsis may be dangerous. Dose: 10mg up to TDS (5mg in elderly/children).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','easy','flashcard','What is the mechanism of action of hyoscine and what are its peripheral anticholinergic side effects?','["Hyoscine (scopolamine) is a tertiary amine muscarinic antagonist that crosses the BBB (unlike quaternary hyoscine butylbromide). It blocks M1, M2, and M3 receptors. Peripheral anticholinergic side effects follow the mnemonic ''SLUD'' reversal: Dry mouth (reduced salivation), Blurred vision (cycloplegia, mydriasis), Urinary retention (detrusor relaxation), Constipation (reduced peristalsis), Tachycardia (M2 blockade in SA node), Dry skin (anhidrosis)."]','A','Central effects (from crossing BBB): drowsiness, confusion, anterograde amnesia (used pre-anaesthesia), and at high doses delirium. Hyoscine is highly anticholinergic and should be avoided in elderly patients (Beers criteria). Transdermal patches (1.5mg/72 hours) are used for motion sickness and post-operative nausea. Topical ophthalmic use for cycloplegia.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','hard','flashcard','Compare the prokinetic mechanisms of metoclopramide, domperidone, erythromycin, and prucalopride.','["Metoclopramide: D2 antagonist (removes dopamine inhibition) + 5-HT4 agonist (stimulates ACh release); crosses BBB → extrapyramidal effects. Domperidone: D2 antagonist; does NOT cross BBB → peripheral prokinesis, no EPS, but QT risk. Erythromycin: motilin receptor agonist → triggers MMC-like contractions; tachyphylaxis develops quickly. Prucalopride: highly selective 5-HT4 agonist → enhances colonic propulsive motility; no cardiac QT risk (no hERG channel blockade)."]','A','This comparison is frequently tested. Key clinical points: (1) Parkinson''s disease → domperidone (no central D2 blockade); (2) Gastroparesis first-line → metoclopramide or domperidone; (3) Chronic constipation → prucalopride; (4) Acute gastroparesis/tube feeding → IV erythromycin short-term. All prokinetics except prucalopride have significant cardiovascular or neurological risks limiting long-term use.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','medium','flashcard','What muscarinic receptor subtype mediates smooth muscle relaxation by hyoscine butylbromide, and why is this clinically important?','["M3 muscarinic receptors are the primary subtype on GI smooth muscle responsible for cholinergic-mediated contraction. Blocking M3 receptors with hyoscine butylbromide relaxes GI smooth muscle, relieving spasm. M3 receptors are also present in the salivary glands (dry mouth), ciliary body/iris (blurred vision, mydriasis), bladder detrusor (urinary retention), and bronchi — explaining the anticholinergic side effects."]','A','Understanding receptor subtype distribution explains why M3 blockade produces both therapeutic (GI antispasm) and adverse (dry mouth, urinary retention, blurred vision) effects simultaneously. Selective M3 antagonists for the bladder (oxybutynin, tolterodine) exploit the same receptor for treating overactive bladder. Truly GI-selective M3 antagonists are an area of ongoing drug development.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 7: Drugs for Hepatic Encephalopathy (10 flashcards)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','easy','flashcard','How does lactulose reduce ammonia levels in hepatic encephalopathy?','["Lactulose is fermented by colonic bacteria to organic acids (lactic, acetic acids), acidifying the colon to pH <6. This converts NH3 (freely diffusible, absorbed across colonic mucosa → crosses BBB → neurotoxic) to NH4+ (ionised ammonium, cannot cross membranes → trapped in colon → excreted in faeces). Lactulose also acts as a laxative, reducing transit time and ammonia absorption."]','A','Target: 2–3 soft stools per day (indicates adequate colonic acidification without excess). Dose: 15–30mL TDS, titrated to response. Rectal administration (300mL in 700mL water as retention enema) is used when oral route is not feasible (coma). Side effects: bloating, flatulence, abdominal cramps. Over-dosing causes diarrhoea → dehydration → electrolyte disturbances → worsening encephalopathy.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','medium','flashcard','What is rifaximin and why is it used in hepatic encephalopathy instead of systemic antibiotics?','["Rifaximin is a rifamycin-derived antibiotic with <0.4% GI absorption. It acts locally in the gut, inhibiting bacterial RNA polymerase and reducing the load of ammonia-producing colonic bacteria without significant systemic toxicity. Unlike neomycin, rifaximin is not nephrotoxic or ototoxic. Used for secondary prevention of hepatic encephalopathy (550mg BD) added to lactulose."]','A','Evidence: Bass et al. NEJM 2010 — rifaximin + lactulose vs lactulose alone: rifaximin reduced breakthrough encephalopathy episodes by 58% and hospitalisations by 50% over 6 months. Rifaximin''s gut-confined action avoids the systemic toxicity of absorbed antibiotics. It does not significantly alter systemic microbiome. Cost is a consideration for long-term use.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','medium','flashcard','Why is neomycin no longer routinely used for hepatic encephalopathy despite historical effectiveness?','["Neomycin reduces ammonia-producing gut bacteria but is an aminoglycoside with systemic toxicity risk. Although poorly absorbed from the gut, small but cumulative systemic absorption occurs, causing: (1) nephrotoxicity — worsened by the already compromised renal function common in advanced cirrhosis; (2) irreversible ototoxicity — sensorineural hearing loss and vestibular damage. Rifaximin achieves equivalent efficacy without these risks."]','A','Neomycin was the historical gold standard before rifaximin became available. In resource-limited settings where rifaximin is unavailable and cost is prohibitive, neomycin may still be used with close monitoring of renal function and audiometry. Metronidazole is another alternative but has different (neurotoxicity, peripheral neuropathy) adverse effects with prolonged use.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','hard','flashcard','What is the current evidence-based pharmacological approach to secondary prevention of hepatic encephalopathy?','["Lactulose (titrated to 2–3 soft stools/day) as the backbone, combined with rifaximin 550mg twice daily. This combination (supported by RCT evidence — Bass et al. NEJM 2010) reduces breakthrough encephalopathy by ~58% compared to lactulose alone. Identify and treat precipitants (infections, GI bleeding, electrolyte disturbances, constipation). Zinc supplementation if deficient. Adequate protein intake maintained (1.2–1.5g/kg/day)."]','A','Common error to avoid: complete protein restriction — this causes sarcopenia, worsening ammonia handling (muscle is a major ammonia detoxification site via glutamine synthesis). Current guidelines recommend adequate protein, preferably from vegetable/dairy sources (less ammoniagenic than meat). BCAA supplementation may be added in patients with muscle wasting and persistent encephalopathy.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','easy','flashcard','What is the target stool frequency when using lactulose for hepatic encephalopathy?','["2–3 soft stools per day. This frequency indicates adequate colonic acidification (NH3 → NH4+ trapping) without excessive diarrhoea. Both extremes are harmful: under-dosing → inadequate ammonia trapping; over-dosing → diarrhoea → dehydration and electrolyte imbalances (especially hypokalaemia and hypernatraemia) → precipitate or worsen encephalopathy."]','A','Patients should be counselled to adjust their own lactulose dose based on stool frequency. Typical starting dose is 15–30mL three times daily with dose adjustments every 2–3 days. In acute encephalopathy requiring hospitalisation, doses may be higher (up to 30mL four times daily) with close monitoring, then reduced once improvement occurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','medium','flashcard','What are the common precipitating factors for hepatic encephalopathy and how are they pharmacologically managed?','["1. GI bleeding (increased ammonia load from blood) → lactulose, consider rifaximin, treat bleeding source. 2. Infections/SBP → broad-spectrum antibiotics (ceftriaxone for SBP + albumin). 3. Constipation → lactulose titration. 4. Hypokalaemia/electrolyte disturbances → correct electrolytes (oral/IV KCl). 5. Renal failure → remove/treat cause, withhold diuretics. 6. Sedative drugs (benzodiazepines, opioids) → withhold if possible; flumazenil for benzo reversal."]','A','The clinical maxim: always search for and treat the precipitant in hepatic encephalopathy — ammonia-lowering therapy alone (lactulose/rifaximin) is insufficient if the precipitant is not corrected. Infection is the most commonly missed precipitant. Consider SBP in any cirrhotic with encephalopathy even without classic peritoneal signs. Diagnostic paracentesis is mandatory.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','hard','flashcard','How do branched-chain amino acids (BCAAs) relate to the pathophysiology of hepatic encephalopathy?','["In cirrhosis, the BCAA:AAA (branched-chain:aromatic amino acid) plasma ratio is reduced. AAAs (phenylalanine, tyrosine, tryptophan) are normally metabolised by the liver; hepatic failure → AAA accumulation. Both BCAAs (valine, leucine, isoleucine) and AAAs compete for the same BBB transporter (LAT1). Elevated AAAs cross the BBB preferentially, forming false neurotransmitters (octopamine from tyrosine) and excess serotonin (from tryptophan), contributing to encephalopathy."]','A','BCAA supplementation theoretically restores the BCAA:AAA ratio, competitively reducing AAA transport across the BBB. Clinical evidence for BCAA supplementation is modest — it may improve nutritional status and reduce encephalopathy episodes in malnourished cirrhotic patients but is not standard therapy. BCAAs are metabolised by muscle (not liver), making them the preferred protein source in cirrhosis.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','easy','flashcard','What is the rationale for rectal lactulose administration in acute hepatic encephalopathy?','["When the oral route is unavailable (unconscious patient, severe vomiting, hepatic coma), lactulose can be administered as a retention enema (300mL lactulose + 700mL water, retained for 1 hour via Foley catheter balloon). This delivers lactulose directly to the colon where its therapeutic effects occur — bacterial fermentation and colonic acidification trapping NH3 as NH4+. No systemic absorption is required for efficacy."]','A','Rectal lactulose can achieve rapid colonic acidification, often with improvement in conscious level within hours if encephalopathy is lactulose-responsive. Cleansing phosphate enemas may be given first to empty faeces and maximise lactulose contact time with colonic mucosa. Oral lactulose is resumed as soon as the patient can swallow safely.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','medium','flashcard','How does zinc supplementation help in hepatic encephalopathy?','["Zinc is an essential cofactor for several urea cycle enzymes, including ornithine transcarbamylase (OTC). Zinc deficiency is common in cirrhosis (reduced intake, increased urinary excretion, malabsorption). Correcting zinc deficiency improves urea cycle capacity, enhancing hepatic ammonia detoxification. Dose: zinc acetate or sulphate 50mg elemental zinc TDS. Evidence shows modest reduction in plasma ammonia and improvement in psychometric tests of encephalopathy."]','A','Zinc supplementation is a safe, inexpensive adjunct to lactulose and rifaximin. It is particularly useful in malnourished cirrhotic patients with demonstrated zinc deficiency. Zinc also acts as an antioxidant and may reduce hepatic fibrosis progression. Adverse effects at therapeutic doses are minimal (nausea at high doses; copper deficiency with very prolonged high-dose use).','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','hard','flashcard','Why is complete dietary protein restriction INCORRECT management for hepatic encephalopathy?','["Protein restriction causes: (1) muscle catabolism and sarcopenia — muscle is a major site of ammonia detoxification via glutamine synthase (converting NH3 + glutamate → glutamine); less muscle → less ammonia clearance → paradoxically worsens encephalopathy; (2) malnutrition worsens cirrhosis prognosis overall. Current guidelines recommend 1.2–1.5g protein/kg/day, with preference for vegetable/dairy proteins (less ammoniagenic) and small, frequent meals."]','A','This represents one of the most important paradigm shifts in hepatic encephalopathy management. The old practice of protein restriction (based on the premise that dietary protein → ammonia → encephalopathy) has been abandoned. Adequate nutrition, especially protein, improves muscle mass (sarcopenia is an independent predictor of mortality in cirrhosis), reduces infection risk, and paradoxically improves ammonia handling.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 8: Liver Disease Pharmacology (10 flashcards)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','easy','flashcard','What is the first-line pharmacological treatment for ascites in cirrhosis and what is the mechanism?','["Spironolactone — an aldosterone antagonist (competitive antagonist at mineralocorticoid receptors in the distal nephron). In cirrhosis, secondary hyperaldosteronism drives renal sodium and water retention, causing ascites. Spironolactone blocks aldosterone receptors, promoting natriuresis (sodium excretion with water following osmotically), reducing ascites. Starting dose 100mg/day, titrate to maximum 400mg/day."]','A','Spironolactone is potassium-sparing, so potassium levels must be monitored (risk of hyperkalaemia). It also has antiandrogenic effects (gynaecomastia in males). If spironolactone alone is insufficient, furosemide (40mg/day) is added, maintaining the 100:40 (spironolactone:furosemide) ratio to preserve electrolyte balance. Target weight loss: 500g/day (no peripheral oedema) or 1kg/day (with peripheral oedema).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','medium','flashcard','Why are non-selective beta-blockers (propranolol, carvedilol) used in cirrhotic patients with oesophageal varices?','["Non-selective beta-blockers (NSBBs) reduce portal hypertension through two mechanisms: (1) beta-1 blockade → reduced cardiac output → reduced portal venous blood flow; (2) beta-2 blockade → splanchnic vasoconstriction (unopposed alpha-1 activity) → reduced portal inflow. Net effect: 15–25% reduction in portal pressure, reducing variceal wall tension and rupture risk. Used for primary prophylaxis (large varices, no prior bleed) and secondary prophylaxis (post-bleed, combined with endoscopic band ligation)."]','A','Contraindications to NSBBs in cirrhosis: severe hypotension (MAP <55 mmHg), severe bradycardia, spontaneous bacterial peritonitis (NSBBs may worsen haemodynamic instability in SBP), refractory ascites (relative — may precipitate hepatorenal syndrome). Carvedilol (non-selective beta + alpha-1 blocker) achieves greater portal pressure reduction than propranolol and is increasingly preferred.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','medium','flashcard','What is terlipressin and what are its two main indications in liver disease?','["Terlipressin is a synthetic vasopressin analogue (prodrug of lysine vasopressin) that acts on V1 receptors on splanchnic arteriolar smooth muscle, causing vasoconstriction and reducing portal pressure. Main indications: (1) Acute variceal haemorrhage — reduces portal pressure, slows bleeding, used as adjunct to endoscopic therapy; (2) Hepatorenal syndrome type 1 (HRS-1) — constricts splanchnic circulation, improving renal perfusion and GFR (combined with IV albumin)."]','A','Terlipressin has a longer half-life than vasopressin (2mg every 4 hours IV bolus vs continuous vasopressin infusion) with fewer systemic vasoconstrictive complications (less peripheral/cardiac ischaemia). Contraindications: peripheral vascular disease, ischaemic heart disease, pregnancy. For variceal bleeding: given for 5 days alongside endoscopic band ligation and antibiotics (ceftriaxone).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','easy','flashcard','What is N-acetylcysteine (NAC) and how does it treat paracetamol overdose?','["NAC is the antidote for paracetamol hepatotoxicity. Paracetamol overdose depletes glutathione (which normally detoxifies the reactive metabolite NAPQI). NAC works by: (1) providing cysteine as a glutathione precursor, replenishing glutathione stores; (2) directly conjugating with and detoxifying NAPQI. Most effective within 8 hours of ingestion but benefits extend to 24 hours or beyond in severe cases. Given IV (Parvolex) or orally."]','A','IV NAC regimen: 150mg/kg in 200mL glucose over 1 hour, then 50mg/kg over 4 hours, then 100mg/kg over 16 hours. In late presenters (>24h) or those with established liver failure, NAC may still benefit by improving hepatic oxygen delivery and reducing organ failure progression. NAC is also used for prevention of contrast nephropathy (less evidence) and some other drug-induced liver injuries.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','hard','flashcard','What is the pharmacological management of acute variceal haemorrhage?','["1. Vasoactive drug: terlipressin 2mg IV q4h (or octreotide/somatostatin) — reduce portal pressure immediately. 2. Antibiotics: ceftriaxone 1g IV daily for 5 days — reduces bacterial translocation and SBP, improves survival. 3. Endoscopic variceal band ligation (EVL) — definitive haemostasis within 12 hours. 4. IV albumin — prevent HRS. 5. Lactulose/rifaximin — prevent encephalopathy from blood in gut. 6. Sengstaken-Blakemore tube if refractory (temporary tamponade)."]','A','The 5-day combination of vasoactive drugs + antibiotics before/during endoscopy is the standard of care. Antibiotics have independently improved survival in variceal bleeding (prophylactic antibiotics reduce infection rate from 40% to 14% and mortality by ~4%). TIPS (transjugular intrahepatic portosystemic shunt) is used for refractory bleeding uncontrolled by endoscopy.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','medium','flashcard','How does octreotide reduce portal pressure and when is it used?','["Octreotide is a synthetic somatostatin analogue acting on SSTR2 and SSTR5 receptors. It suppresses glucagon release from pancreatic alpha cells. Glucagon is a potent splanchnic vasodilator; its suppression leads to splanchnic vasoconstriction, reducing portal venous inflow and portal pressure. Also has direct vasoconstrictor effects on splanchnic vessels. Used in acute variceal haemorrhage (adjunct to endoscopy) and as prophylaxis during endoscopy."]','A','Octreotide is given as IV bolus (50 micrograms) followed by infusion (50 micrograms/hour) for 5 days in acute variceal bleeding. It is generally better tolerated than terlipressin (less peripheral vasoconstriction). Somatostatin itself (t1/2 ~2 minutes) requires continuous infusion. Octreotide is also used for carcinoid syndrome, acromegaly, VIPoma, and as a bowel rest agent in high-output fistulae.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','medium','flashcard','Why are NSAIDs absolutely contraindicated in decompensated cirrhosis with ascites?','["In cirrhosis with ascites, renal perfusion is critically dependent on prostaglandin (PGE2, PGI2)-mediated vasodilation of renal afferent arterioles to compensate for reduced effective circulating volume (splanchnic vasodilation, low albumin). NSAIDs inhibit COX-1 and COX-2, reducing renal prostaglandin synthesis → afferent arteriolar constriction → acute kidney injury → precipitates hepatorenal syndrome. Even single-dose NSAID use can trigger HRS in these patients."]','A','Safe analgesics in cirrhosis: paracetamol (acetaminophen) is the preferred analgesic at doses ≤2g/day (or ≤1.5g/day in heavy drinkers/malnutrition) — dose-dependent hepatotoxicity risk is manageable at these doses. Opioids can be used cautiously (reduce dose, extended dosing intervals) but risk precipitating encephalopathy. NSAIDs including COX-2 inhibitors are contraindicated.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','hard','flashcard','What is hepatorenal syndrome (HRS) and what is its pharmacological treatment?','["HRS is functional renal failure in advanced cirrhosis/acute liver failure without intrinsic kidney pathology, caused by extreme splanchnic vasodilation and renal vasoconstriction reducing GFR. Type 1 (HRS-1): rapidly progressive (creatinine doubles to >226 μmol/L within 2 weeks); Type 2 (HRS-2): slower course, associated with refractory ascites. Treatment: terlipressin 1–2mg IV every 4–6 hours + IV albumin 1g/kg (up to 100g) on day 1, then 20–40g/day for up to 14 days."]','A','Terlipressin + albumin reverses HRS in ~40–50% of patients (creatinine falls to <133 μmol/L). Hypovolaemia must be excluded first (albumin challenge). Alternatives where terlipressin is unavailable: noradrenaline + albumin (similar efficacy in ITU setting), or midodrine + octreotide + albumin (oral regimen, lower efficacy). Definitive treatment: liver transplantation. TIPS is a bridging option.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','easy','flashcard','What is the recommended spironolactone:furosemide dosing ratio for ascites and why is this ratio maintained?','["The 100mg:40mg (spironolactone:furosemide) ratio is maintained during dose escalation (e.g., 200:80, 300:120, maximum 400:160). This ratio is empirically derived to counterbalance furosemide''s potassium-wasting effect with spironolactone''s potassium-sparing effect, maintaining normokalemia. If the ratio is disrupted: too much furosemide → hypokalaemia; too much spironolactone → hyperkalaemia."]','A','Electrolytes and renal function should be checked every 1–2 weeks when titrating diuretics for ascites, then monthly when stable. Target: weight loss ≤500g/day (no oedema) or ≤1kg/day (with oedema) to avoid too-rapid fluid mobilisation causing electrolyte imbalances and AKI. Diuretics should be stopped if: creatinine >177 μmol/L, sodium <120 mmol/L, or hepatic encephalopathy develops.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','hard','flashcard','What is the pharmacological treatment and antibiotic of choice for spontaneous bacterial peritonitis (SBP)?','["Treatment: IV ceftriaxone 1g daily (or IV cefotaxime 2g 8-hourly) for 5 days. Intravenous albumin (1.5g/kg on day 1, 1g/kg on day 3) is given concurrently to prevent hepatorenal syndrome (reduces HRS risk from 33% to 10% and improves survival). Secondary prophylaxis: oral norfloxacin 400mg/day (or ciprofloxacin 500mg/day) indefinitely after first episode."]','A','Primary prophylaxis of SBP is recommended for: high-risk cirrhotic patients (ascites protein <15g/L + Child-Pugh ≥9 or bilirubin ≥3mg/dL, or renal impairment/hyponatraemia) — use norfloxacin 400mg/day. The SBP diagnosis requires >250 PMN/mm3 in ascitic fluid. Most common organisms: E. coli, Klebsiella, Streptococcus pneumoniae. Third-generation cephalosporins cover these effectively.','universal',true,'{year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

-- SUBTOPIC 9: Pancreatic Enzyme Supplements & Ursodeoxycholic Acid (10 flashcards)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','easy','flashcard','What enzymes does pancreatin (Creon) contain and what condition is it used for?','["Pancreatin (e.g., Creon) contains porcine-derived lipase, amylase, and protease (pancrelipase). It is used for exocrine pancreatic insufficiency (EPI) — failure of the exocrine pancreas to produce sufficient digestive enzymes, causing malabsorption, steatorrhoea (bulky, pale, offensive, greasy stools), weight loss, and fat-soluble vitamin deficiencies (A, D, E, K). Common causes: chronic pancreatitis, cystic fibrosis, pancreatectomy."]','A','Lipase is the most critical enzyme — fat malabsorption is the dominant feature of EPI. Creon is available in different strengths (Creon 10000, 25000, 40000 — units refer to lipase content per capsule). Dose is titrated to symptom control (typically 25,000–75,000 lipase units per meal). Take with meals/snacks. Enteric coating protects enzymes from gastric acid.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','medium','flashcard','When should pancreatin capsules be taken and what is the important counselling point about opening capsules?','["Take during or immediately after meals. For infants/children who cannot swallow capsules: open the capsule and sprinkle microspheres onto a small amount of acidic food (pH <5.5 — e.g., unsweetened apple sauce, fruit juice). NEVER mix with alkaline foods (breast milk, formula, pH >5.5), as this dissolves the enteric coating, exposing enzymes to gastric acid inactivation. NEVER crush or chew the microspheres."]','A','The timing is critical: food stimulates CCK release, which triggers endogenous pancreatic secretion (creating conditions for enzyme mixing in the duodenum). Enzyme supplementation should mimic this timing. If taken too early (>30 min before meals), the enzyme will have passed beyond the duodenum before food arrives. A dose should also be taken with snacks.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','hard','flashcard','What is fibrosing colonopathy and what is the key risk factor?','["Fibrosing colonopathy is a rare but serious complication of pancreatin therapy characterised by submucosal fibrosis of the colon causing strictures, predominantly in the right colon. It presents with abdominal pain, bloody diarrhoea, and bowel obstruction. The key risk factor is high-dose pancreatin exceeding 10,000 lipase units/kg/day, particularly in children with cystic fibrosis receiving high-strength preparations."]','A','The mechanism is not fully established — may involve the methacrylic acid copolymer (Eudragit L) enteric coating or direct enzyme toxicity to colonic mucosa. UK guidelines recommend not exceeding 10,000 lipase units/kg/day in children. If symptoms suggesting fibrosing colonopathy develop, pancreatin dose should be reduced and colonoscopy performed. Surgical resection may be needed for established strictures.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','easy','flashcard','What is ursodeoxycholic acid (UDCA) and what is its mechanism of action in primary biliary cholangitis (PBC)?','["UDCA is a hydrophilic (non-toxic) bile acid that constitutes <5% of normal bile. In PBC, it: (1) displaces cytotoxic hydrophobic bile acids (chenodeoxycholic, deoxycholic) from the bile acid pool, making bile less injurious to biliary epithelium; (2) stimulates bile secretion (choleresis), reducing intrahepatic cholestasis; (3) has immunomodulatory effects (reduces MHC class I expression on cholangiocytes); (4) has anti-apoptotic effects on cholangiocytes."]','A','UDCA at 13–15 mg/kg/day slows PBC progression, reduces ALP and bilirubin, delays histological progression, and reduces the need for liver transplantation when started early. Approximately 40% of patients achieve a complete biochemical response (ALP normalisation). Non-responders may benefit from add-on therapy with obeticholic acid (FXR agonist) or fibrates.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','medium','flashcard','What dose of ursodeoxycholic acid is used for primary biliary cholangitis versus cholesterol gallstone dissolution?','["PBC: 13–15 mg/kg/day in divided doses (2–4 doses daily). Gallstone dissolution: 8–10 mg/kg/day (lower dose, as goal is to desaturate bile of cholesterol rather than replace the entire bile acid pool). For gallstones, treatment duration is 6–24 months, and only small (<1cm), radiolucent (non-calcified), cholesterol gallstones in a functioning gallbladder are amenable."]','A','High-dose UDCA (28–30mg/kg/day) is HARMFUL in primary sclerosing cholangitis (PSC) — a large RCT showed increased adverse events and mortality. This contrasts with PBC where standard doses are beneficial. UDCA does not work for calcified (radio-opaque) gallstones, pigment stones, or non-functioning gallbladders (blocked cystic duct). Gallstones can recur after stopping UDCA (50% recurrence at 5 years).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','medium','flashcard','What is the importance of adding a PPI when pancreatin therapy is insufficient for steatorrhoea?','["In some patients (especially cystic fibrosis), gastric acid hypersecretion or slow gastric emptying keeps duodenal pH low (<5.5), causing premature dissolution of enteric coating of pancreatin microspheres or directly inactivating uncoated enzyme preparations before they can work. Adding a PPI or H2 blocker raises duodenal pH, ensuring enteric-coated microspheres dissolve correctly in the proximal small intestine and enzymes remain active. This is preferable to escalating pancreatin dose (fibrosing colonopathy risk)."]','A','This intervention should be tried in any patient with persistent steatorrhoea despite adequate pancreatin dosing (confirmed by compliance). It is particularly relevant in cystic fibrosis patients (who have increased acid secretion and impaired pancreatic bicarbonate secretion). A trial of omeprazole 20mg or ranitidine 150mg twice daily with meals is appropriate before dose escalation.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','hard','flashcard','Why does UDCA fail to dissolve calcified (radio-opaque) gallstones?','["UDCA dissolves cholesterol gallstones by desaturating bile (reducing cholesterol secretion into bile) and directly solubilising cholesterol crystals from the stone surface via mixed micelle formation. Calcified gallstones have calcium bilirubinate or calcium carbonate deposited throughout the stone structure. These calcium salts are insoluble in bile regardless of bile acid composition — UDCA cannot dissolve inorganic calcium salts. Calcification also appears on plain abdominal X-ray as radio-opaque stones."]','A','Approximately 10–15% of cholesterol gallstones have visible calcification on plain X-ray, making them unsuitable for UDCA therapy. CT scan is more sensitive for detecting calcification. Even ''pure'' cholesterol stones may have a calcified rim (''eggshell'' calcification) making them UDCA-resistant. Overall, only ~15–20% of all gallstone patients are suitable candidates for medical dissolution.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','easy','flashcard','What fat-soluble vitamins are deficient in exocrine pancreatic insufficiency and why?','["Vitamins A, D, E, and K are fat-soluble and require bile and pancreatic enzymes (lipase) for incorporation into mixed micelles and absorption in the small intestine. In EPI, lipase deficiency causes fat malabsorption (steatorrhoea) and concurrent malabsorption of fat-soluble vitamins. This leads to: night blindness (vitamin A), osteomalacia/rickets (vitamin D), neurological degeneration (vitamin E), and coagulopathy (vitamin K — prolonged PT/INR)."]','A','Fat-soluble vitamin deficiency should be screened for in all patients with EPI: serum retinol (Vit A), 25-OH vitamin D, alpha-tocopherol (Vit E), and PT/INR (Vit K). Replacement: oral fat-soluble vitamin supplements with meals (taken simultaneously with pancreatin so enzymes are present to aid their absorption). Vitamin D and calcium supplementation is particularly important to prevent metabolic bone disease in chronic pancreatitis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','medium','flashcard','What is the evidence for and against UDCA in primary sclerosing cholangitis (PSC)?','["Against: A large RCT (Lindor et al. Hepatology 2009) of high-dose UDCA (28–30 mg/kg/day) in PSC showed significantly increased rates of serious adverse events (variceal haemorrhage, liver transplantation, death) compared to placebo — this dose is now CONTRAINDICATED in PSC. For: Standard-dose UDCA (13–15 mg/kg/day) improves liver biochemistry (ALP) in PSC but has NOT demonstrated survival benefit in RCTs. Current major guidelines do not recommend UDCA routinely for PSC outside clinical trials."]','A','This is an important clinical distinction: UDCA is clearly beneficial in PBC (standard dose), clearly harmful at high dose in PSC, and uncertain at standard dose in PSC. The reasons for the harmful effect of high-dose UDCA in PSC are unclear — possibly related to altered bile acid pool toxicity or promotion of carcinogenesis in dysplastic biliary epithelium. Ongoing trials assess lower doses.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','hard','flashcard','Why must pancreatin microspheres NOT be mixed with alkaline foods (breast milk, formula) when opening Creon capsules for infants?','["Pancreatin microspheres have an enteric coating (pH-sensitive polymer, Eudragit L30D-55) designed to dissolve only at pH >5.5, delivering enzymes to the duodenum and protecting them from gastric acid inactivation. Breast milk (pH ~7.2) and infant formula (pH ~6.5–7.0) are alkaline (pH >5.5), which immediately dissolves the enteric coating in the food — exposing enzymes to gastric acid upon ingestion, causing irreversible lipase inactivation and therapeutic failure."]','A','Correct administration for infants: mix microspheres with a small amount of slightly acidic food (unsweetened apple sauce, fruit juice, pH <5.5) immediately before feeding. The enzymes are then protected in the stomach and released at the correct site in the duodenum. Mixing with water (pH ~7) is also incorrect for the same reason. This counselling point is critical for parents of infants with cystic fibrosis on Creon.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 10: GI Drug Interactions & Adverse Effects (10 flashcards)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','easy','flashcard','How do NSAIDs cause peptic ulceration and what drugs protect against this?','["NSAIDs inhibit COX-1 (constitutively expressed in gastric mucosa), reducing prostaglandin E2 (PGE2). PGE2 normally: (1) stimulates mucus and bicarbonate secretion; (2) maintains mucosal blood flow; (3) inhibits parietal cell acid secretion. Loss of these protective mechanisms leads to ulceration. Protection: co-prescribe a PPI (omeprazole 20mg daily) or misoprostol (PGE1 analogue). Selective COX-2 inhibitors (celecoxib) cause less GI damage."]','A','Important: NSAID-induced ulcers occur even with systemic/parenteral/suppository administration — the damage is from loss of systemic prostaglandin synthesis, not local mucosal contact. Risk factors for NSAID-induced ulcer: age >60, previous peptic ulcer, concurrent anticoagulant or corticosteroid use, high-dose or multiple NSAIDs, H. pylori co-infection. All high-risk patients should receive PPI prophylaxis with any NSAID.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','medium','flashcard','What is the cardiovascular risk associated with COX-2 selective inhibitors (celecoxib, etoricoxib)?','["COX-2 inhibitors block vascular endothelial prostacyclin (PGI2) production (PGI2 is vasodilatory and anti-platelet) without affecting platelet thromboxane A2 (TXA2) production (pro-thrombotic, requires only COX-1). This shifts the haemostatic balance towards thrombosis. COX-2 inhibitors significantly increase risk of MI, stroke, and peripheral arterial events. This led to rofecoxib (Vioxx) withdrawal in 2004. COX-2 inhibitors are contraindicated in established cardiovascular disease."]','A','The protective GI profile of COX-2 inhibitors versus the increased CV risk means their net benefit depends on individual patient risk profile. A patient with high GI risk but no CV risk benefits from celecoxib; one with both GI and CV risk should use the lowest-dose non-selective NSAID + PPI. Celecoxib also inhibits CYP2C9, increasing warfarin levels — INR monitoring required.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','medium','flashcard','What GI side effects does metformin cause and how are they minimised?','["Metformin causes GI side effects in ~30% of patients: nausea, vomiting, diarrhoea, abdominal cramping, metallic taste. These are dose-related and related to peak plasma concentration. Minimisation strategies: (1) Start at low dose (500mg once daily with breakfast); (2) Titrate slowly over 4–8 weeks; (3) Always take with or immediately after food; (4) Use modified-release formulation (Glucophage SR) — slower absorption, lower peak levels, fewer GI side effects (~23% vs ~30% with standard release)."]','A','GI side effects are the most common reason for metformin discontinuation, particularly problematic as metformin is the safest and most effective first-line oral agent for type 2 diabetes. They generally improve over 4–6 weeks as GI tolerance develops. Serious GI toxicity (severe diarrhoea causing dehydration) requires temporary cessation to prevent AKI and lactic acidosis accumulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','hard','flashcard','In which specific GI-related clinical scenario is metformin-induced lactic acidosis most likely to occur?','["Acute severe gastroenteritis causing significant dehydration → pre-renal AKI (reduced GFR) → metformin accumulates (normally renally cleared) → marked inhibition of mitochondrial complex I and hepatic gluconeogenesis → lactic acid accumulation (impaired lactate clearance) → potentially fatal lactic acidosis. Risk is also high in: contrast-induced AKI (iodinated contrast media), severe infection with haemodynamic compromise, major surgery."]','A','Sick-day guidance: metformin should be temporarily withheld during any acute illness likely to cause dehydration, reduced oral intake, or AKI. The ''sick day rules'' are: stop metformin if vomiting, unable to drink, or if feverish/unwell. Restart 48 hours after recovery and confirmed adequate renal function. eGFR thresholds: reduce dose if eGFR 30–45 mL/min; contraindicated if eGFR <30 mL/min.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','medium','flashcard','What is the mechanism of the tetracycline-dairy/antacid/iron interaction and how should it be managed?','["Tetracyclines contain keto and hydroxyl groups that chelate divalent (Ca2+, Mg2+, Fe2+) and trivalent (Al3+, Fe3+) metal ions, forming insoluble, non-absorbable complexes. This reduces tetracycline bioavailability by 50–80%. Sources: dairy products (Ca2+), antacids (Al3+, Mg2+, Ca2+), iron supplements, zinc, bismuth. Management: take tetracyclines on an empty stomach, 1–2 hours before or 4–6 hours after any of these substances."]','A','The same chelation mechanism applies to fluoroquinolones (ciprofloxacin, levofloxacin) but to a lesser extent (~50% bioavailability reduction). This class of interaction (chelation) also affects bisphosphonates (alendronate must be taken with plain water only, 30 min before food/any other medication). Clinical implication: a patient taking iron for anaemia and doxycycline for infection must separate the doses by at least 4 hours.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','medium','flashcard','By approximately how much do magnesium/aluminium antacids reduce ciprofloxacin absorption and what is the mechanism?','["Antacids containing Mg2+ or Al3+ reduce ciprofloxacin oral bioavailability by approximately 50% through chelation. Ciprofloxacin''s 3-carboxylic acid and 4-oxo groups chelate divalent/trivalent cations, forming poorly soluble complexes that cannot be absorbed across the intestinal epithelium. The same interaction occurs with other fluoroquinolones (levofloxacin, moxifloxacin) and with iron, sucralfate, calcium, and dairy products."]','A','Clinical management: take ciprofloxacin at least 2 hours before or 4–6 hours after antacids, iron, sucralfate, or dairy. This interaction has clinical significance — treatment failure of community-acquired infections or urinary tract infections can result if patients self-medicate with antacids without separating doses. Pharmacists should counsel patients on this interaction at point of dispensing.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','easy','flashcard','What GI side effects does oral iron cause and how should patients be counselled?','["1. Constipation (most common) — iron reduces gut motility. 2. Black/dark stools — iron sulphide formation from unabsorbed iron (HARMLESS — distinguish from melaena which is tarry and offensive-smelling). 3. Nausea, epigastric pain — reduced by taking iron with food (though food reduces absorption by ~50%). 4. Diarrhoea (less common). Counselling: black stools are expected and not a sign of bleeding; take with food if GI effects are severe."]','A','Standard preparation: ferrous sulphate 200mg TDS (contains 65mg elemental iron per tablet). Ferrous gluconate and ferrous fumarate are alternatives with comparable absorption but slightly different elemental iron content and GI side effect profiles. Ferric maltol (Feraccru) and ferric derisomaltose (IV) are used when oral iron is not tolerated. Vitamin C (ascorbic acid) 200mg with each dose enhances non-haem iron absorption.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','hard','flashcard','What is the pharmacokinetic interaction between celecoxib and warfarin and what is the clinical significance?','["Celecoxib inhibits CYP2C9, the primary enzyme responsible for S-warfarin metabolism (S-warfarin is 3–5 times more potent than R-warfarin and is metabolised by CYP2C9). Inhibition reduces S-warfarin clearance → elevated S-warfarin plasma levels → prolonged INR → increased bleeding risk. This is particularly dangerous as both drugs increase bleeding risk through different mechanisms (celecoxib → reduced PGI2 → platelet function impaired; warfarin → anticoagulation)."]','A','Management: if celecoxib is initiated in a warfarin patient, INR should be checked more frequently (at 3–5 days, then weekly for the first month). Warfarin dose reduction may be needed. Note: all NSAIDs increase bleeding risk in anticoagulated patients via gastric mucosal effects, even without a pharmacokinetic interaction. Paracetamol at doses >2g/day also modestly elevates INR in warfarin-treated patients (CYP2C9 independent mechanism).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','medium','flashcard','What is the mechanism by which proton pump inhibitors reduce absorption of ketoconazole and itraconazole?','["Ketoconazole and itraconazole are azole antifungals with weak base properties that require an acidic gastric environment (pH <3) for adequate dissolution and absorption. PPIs raise intragastric pH to 4–7, dramatically reducing dissolution of these drugs. Ketoconazole bioavailability can fall by >80% with concurrent PPI use. Similarly, atazanavir, iron (ferric salts), and calcium carbonate all require acid for absorption."]','A','Solutions: (1) Use itraconazole oral solution (in hydroxypropyl-beta-cyclodextrin) instead of capsules — the solution form has acid-independent absorption; (2) Switch to voriconazole or fluconazole (not pH-dependent for absorption); (3) Use acidic beverages (cola drinks, pH ~2.5) with capsule formulations (limited evidence). For HIV patients on atazanavir: PPIs are contraindicated; use H2 blockers at lower doses if acid suppression is needed.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','hard','flashcard','Summarise the key GI drug interactions involving absorption that a prescriber must know.','["1. PPIs/H2 blockers ↓: ketoconazole, itraconazole, atazanavir, iron (ferric), calcium carbonate absorption (all need acidic pH). 2. Antacids (Al3+, Mg2+) ↓: tetracyclines, fluoroquinolones, bisphosphonates, iron absorption (chelation). 3. Food ↓: tetracycline, bisphosphonates, captopril absorption (take on empty stomach). 4. Food ↑: iron absorption (acid reduces chelation); grapefruit ↑: CYP3A4 substrates (statin, tacrolimus, ciclosporin). 5. Sucralfate ↓: ciprofloxacin, digoxin, phenytoin (chelation/adsorption)."]','A','These interactions are clinically important because they can cause therapeutic failure (antibiotics, antifungals, HIV drugs) or toxicity (grapefruit + statins → myopathy). The unifying concepts are: (1) pH-dependent absorption requires checking for acid-suppressing drugs; (2) chelation by polyvalent cations requires dose separation; (3) food effects require specific timing instructions. All these should be communicated at point of prescribing and dispensing.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition');
